#!/usr/bin/env node
// scripts/tbc/verify-residual.mjs
//
// SPEC: THINK_BUILD_CHECK.md §6.4
//   "Fails closure when the residual sorted by confidence_it_does_not_matter
//    descending has opened_at: null at the top. Implements A36's ranking rule
//    mechanically."
//
// A36: confidence about irrelevance is generated by the summary, and the
// summary is exactly what is wrong. The cached label that made it feel
// irrelevant is the cached label that let you violate it. So the queue is read
// from the TOP of the confidence-it-does-not-matter ranking, not the bottom.

import { join } from "node:path";
import { exists, read, run, currentBuildDir, jsonBlocks, rawJsonBlocks, repoRel } from "./lib.mjs";

const RANK = { high: 3, medium: 2, low: 1 };

run("tbc:residual", (r) => {
  const dir = currentBuildDir();
  if (!dir) {
    r.fail("§4", "No build directory under docs/tbc/.");
    return;
  }
  const rel = repoRel(dir);

  const closurePath = join(dir, "closure.md");
  if (!exists(closurePath)) {
    // Not at closure yet — this gate only binds closure. Stay quiet.
    r.note("closure.md absent — gate binds at closure only.");
    return;
  }
  const closure = read(closurePath);

  const raw = rawJsonBlocks(closure);
  const parsed = jsonBlocks(closure);
  if (raw.length !== parsed.length) {
    r.fail("§4", `${raw.length - parsed.length} json block(s) in closure.md failed to parse.`);
  }

  const residual = parsed
    .flatMap((b) => (Array.isArray(b) ? b : [b]))
    .filter((e) => e && typeof e === "object" && "confidence_it_does_not_matter" in e);

  if (residual.length === 0) {
    r.fail("§4 / A36",
      "closure.md declares no residual entries.",
      "A36: an empty residual is not a clean audit, it is an unexamined one.\n" +
      "Seven times the agent asserted 'no obvious hook'; seven times it was wrong.\n" +
      "If nothing was skipped, say so as a schema'd entry with the reasoning.");
    return;
  }
  r.note(`${residual.length} residual entr(ies) in ${rel}/closure.md`);

  // schema validation
  for (const e of residual) {
    for (const k of ["id", "item", "why_skipped", "confidence_it_does_not_matter"]) {
      if (!e[k]) r.fail("§4", `residual "${e.id ?? "?"}" is missing "${k}".`);
    }
    const c = String(e.confidence_it_does_not_matter).toLowerCase();
    if (!(c in RANK)) {
      r.fail("§4", `residual "${e.id ?? "?"}": confidence_it_does_not_matter must be high|medium|low, got "${e.confidence_it_does_not_matter}".`);
    }
    if (!("opened_at" in e)) {
      r.fail("§4", `residual "${e.id ?? "?"}" is missing "opened_at" (use null if unopened).`);
    }
  }

  // A36's ranking rule
  const ranked = [...residual].sort(
    (a, b) =>
      (RANK[String(b.confidence_it_does_not_matter).toLowerCase()] ?? 0) -
      (RANK[String(a.confidence_it_does_not_matter).toLowerCase()] ?? 0)
  );

  const top = ranked[0];
  if (!top) return;

  if (top.opened_at === null || top.opened_at === undefined || top.opened_at === "") {
    r.fail("§6.4 / A36",
      `Top-ranked residual "${top.id}" is unopened.`,
      `item: ${top.item}\n` +
      `why_skipped: ${top.why_skipped}\n` +
      `confidence_it_does_not_matter: ${top.confidence_it_does_not_matter}\n\n` +
      "A36: read from the TOP of this ranking. The entry you are most sure does\n" +
      "not matter is the one whose cached summary is most likely to be the thing\n" +
      "that is wrong. Open it, record opened_at and outcome, then close.");
  } else {
    r.note(`top residual "${top.id}" opened at ${top.opened_at} — outcome: ${top.outcome ?? "(none recorded)"}`);
    if (!top.outcome) {
      r.fail("§4", `residual "${top.id}" was opened but records no outcome.`,
        "An opened residual with no outcome is a read that produced nothing on the record.");
    }
  }
});
